import { Market, Product, Price } from '../types';
import { INITIAL_MARKETS, INITIAL_PRODUCTS, INITIAL_PRICES } from './mockData';

const KEY_MARKETS = 'economiza_markets';
const KEY_PRODUCTS = 'economiza_products';
const KEY_PRICES = 'economiza_prices';

// Initialize DB if empty
const initDB = () => {
  if (!localStorage.getItem(KEY_MARKETS)) {
    localStorage.setItem(KEY_MARKETS, JSON.stringify(INITIAL_MARKETS));
  }
  if (!localStorage.getItem(KEY_PRODUCTS)) {
    localStorage.setItem(KEY_PRODUCTS, JSON.stringify(INITIAL_PRODUCTS));
  }
  if (!localStorage.getItem(KEY_PRICES)) {
    localStorage.setItem(KEY_PRICES, JSON.stringify(INITIAL_PRICES));
  }
};

initDB();

export const DB = {
  getMarkets: (): Market[] => JSON.parse(localStorage.getItem(KEY_MARKETS) || '[]'),
  getProducts: (): Product[] => JSON.parse(localStorage.getItem(KEY_PRODUCTS) || '[]'),
  getPrices: (): Price[] => JSON.parse(localStorage.getItem(KEY_PRICES) || '[]'),

  saveMarket: (market: Market) => {
    const markets = DB.getMarkets();
    const index = markets.findIndex(m => m.id === market.id);
    if (index >= 0) markets[index] = market;
    else markets.push(market);
    localStorage.setItem(KEY_MARKETS, JSON.stringify(markets));
  },

  deleteMarket: (id: string) => {
    const markets = DB.getMarkets().filter(m => m.id !== id);
    localStorage.setItem(KEY_MARKETS, JSON.stringify(markets));
  },

  saveProduct: (product: Product) => {
    const products = DB.getProducts();
    const index = products.findIndex(p => p.id === product.id);
    if (index >= 0) products[index] = product;
    else products.push(product);
    localStorage.setItem(KEY_PRODUCTS, JSON.stringify(products));
  },

  deleteProduct: (id: string) => {
    const products = DB.getProducts().filter(p => p.id !== id);
    localStorage.setItem(KEY_PRODUCTS, JSON.stringify(products));
  },

  savePrice: (price: Price) => {
    const prices = DB.getPrices();
    // Rule: One active price per product per market
    const existingIndex = prices.findIndex(p => p.produto_id === price.produto_id && p.mercado_id === price.mercado_id);

    if (existingIndex >= 0) {
      prices[existingIndex] = price; // Update existing
    } else {
      prices.push(price); // Add new
    }
    localStorage.setItem(KEY_PRICES, JSON.stringify(prices));
  },

  // Helper to get lowest price
  getLowestPriceForProduct: (productId: string): number | null => {
    const prices = DB.getPrices()
      .filter(p => p.produto_id === productId && p.ativo && p.valor > 0)
      .sort((a, b) => a.valor - b.valor);

    return prices.length > 0 ? prices[0].valor : null;
  }
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User } from '../types';

interface AuthContextType {
  user: User | null;
  login: (email: string, pass: string) => Promise<boolean>;
  logout: () => void;
  isAdmin: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  // Load from session storage for persistence on refresh
  useEffect(() => {
    const stored = sessionStorage.getItem('economiza_user');
    if (stored) {
      setUser(JSON.parse(stored));
    }
  }, []);

  const login = async (email: string, pass: string): Promise<boolean> => {
    // Mock Authentication Logic
    // In a real app, this would hit the API and verify bcrypt hash
    if (email === 'admin@economiza.com' && pass === 'admin123') {
      const adminUser: User = {
        id: 'admin-1',
        nome: 'Administrador',
        email,
        perfil: 'ADMIN'
      };
      setUser(adminUser);
      sessionStorage.setItem('economiza_user', JSON.stringify(adminUser));
      return true;
    }
    return false;
  };

  const logout = () => {
    setUser(null);
    sessionStorage.removeItem('economiza_user');
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, isAdmin: user?.perfil === 'ADMIN' }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

