import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Search, Filter } from 'lucide-react';
import { DB } from '../services/db';
import { Product } from '../types';

export const Home: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [filteredProducts, setFilteredProducts] = useState<Product[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('Todas');
  const [categories, setCategories] = useState<string[]>([]);

  useEffect(() => {
    const allProducts = DB.getProducts();
    setProducts(allProducts);
    setFilteredProducts(allProducts);

    // Extract categories
    const cats = Array.from(new Set(allProducts.map(p => p.categoria)));
    setCategories(['Todas', ...cats]);
  }, []);

  useEffect(() => {
    let result = products;

    if (searchTerm) {
      result = result.filter(p => p.nome.toLowerCase().includes(searchTerm.toLowerCase()));
    }

    if (selectedCategory !== 'Todas') {
      result = result.filter(p => p.categoria === selectedCategory);
    }

    setFilteredProducts(result);
  }, [searchTerm, selectedCategory, products]);

  const getLowestPrice = (productId: string) => {
    return DB.getLowestPriceForProduct(productId);
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-12">
      {/* Hero / Search Section */}
      <div className="bg-emerald-600 py-12 px-4 sm:px-6 lg:px-8 shadow-md">
        <div className="max-w-3xl mx-auto text-center">
          <h1 className="text-3xl font-extrabold text-white sm:text-4xl">
            Compare preços e economize
          </h1>
          <p className="mt-4 text-emerald-100 text-lg">
            Encontre o menor preço nos mercados da sua região.
          </p>

          <div className="mt-8 relative max-w-xl mx-auto">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Search className="h-5 w-5 text-gray-400" />
            </div>
            <input
              type="text"
              className="block w-full pl-10 pr-3 py-3 border border-transparent rounded-lg leading-5 bg-white text-gray-900 placeholder-gray-500 focus:outline-none focus:bg-white focus:ring-2 focus:ring-emerald-400 sm:text-sm shadow-sm"
              placeholder="Buscar produtos (ex: Arroz, Leite)..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
      </div>

      {/* Filters & Grid */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-8">
        <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
          <h2 className="text-xl font-bold text-gray-800">Produtos Disponíveis</h2>

          <div className="flex items-center space-x-2">
            <Filter size={20} className="text-gray-500" />
            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-emerald-500 focus:border-emerald-500 sm:text-sm rounded-md shadow-sm border"
            >
              {categories.map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>
        </div>

        {filteredProducts.length === 0 ? (
          <div className="text-center py-20 text-gray-500">
            Nenhum produto encontrado. Tente outra busca.
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
            {filteredProducts.map(product => {
              const lowestPrice = getLowestPrice(product.id);
              return (
                <Link key={product.id} to={`/product/${product.id}`} className="group block">
                  <div className="bg-white rounded-lg shadow-sm hover:shadow-md transition-shadow duration-200 overflow-hidden border border-gray-100 h-full flex flex-col">
                    <div className="aspect-w-1 aspect-h-1 w-full bg-gray-200 h-48 relative">
                      <img
                        src={product.imagem_url || "https://picsum.photos/200/200"}
                        alt={product.nome}
                        className="w-full h-full object-cover group-hover:opacity-90 transition-opacity"
                      />
                      <div className="absolute top-2 right-2 bg-emerald-100 text-emerald-800 text-xs px-2 py-1 rounded-full font-semibold">
                        {product.categoria}
                      </div>
                    </div>
                    <div className="p-4 flex-1 flex flex-col justify-between">
                      <div>
                        <h3 className="text-lg font-semibold text-gray-900 group-hover:text-emerald-600 transition-colors">
                          {product.nome}
                        </h3>
                      </div>
                      <div className="mt-4">
                        <p className="text-sm text-gray-500">Melhor preço a partir de:</p>
                        <p className="text-2xl font-bold text-emerald-600">
                          {lowestPrice ? `R$ ${lowestPrice.toFixed(2).replace('.', ',')}` : 'Indisponível'}
                        </p>
                      </div>
                    </div>
                  </div>
                </Link>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ArrowLeft, Calendar, Store } from 'lucide-react';
import { DB } from '../services/db';
import { Product, Price, Market, PriceComparison } from '../types';

export const ProductDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [product, setProduct] = useState<Product | null>(null);
  const [comparisons, setComparisons] = useState<PriceComparison[]>([]);

  useEffect(() => {
    if (!id) return;

    const products = DB.getProducts();
    const foundProduct = products.find(p => p.id === id);
    setProduct(foundProduct || null);

    if (foundProduct) {
      const prices = DB.getPrices().filter(p => p.produto_id === id && p.ativo);
      const markets = DB.getMarkets();

      // Find lowest price value for flagging
      const minPrice = Math.min(...prices.map(p => p.valor));

      const comps: PriceComparison[] = prices.map(price => {
        const market = markets.find(m => m.id === price.mercado_id);
        return {
          marketName: market ? market.nome : 'Mercado Desconhecido',
          price: price.valor,
          lastUpdate: price.data_atualizacao,
          isLowest: price.valor === minPrice && minPrice > 0
        };
      }).sort((a, b) => a.price - b.price); // Sort by price ascending [RF09]

      setComparisons(comps);
    }
  }, [id]);

  if (!product) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center text-gray-500">
        <h2 className="text-2xl font-bold mb-4">Produto não encontrado</h2>
        <Link to="/" className="text-emerald-600 hover:underline">Voltar para Home</Link>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-10">
      <Link to="/" className="inline-flex items-center text-gray-500 hover:text-emerald-600 mb-6 transition-colors">
        <ArrowLeft className="mr-2 h-5 w-5" />
        Voltar para a lista
      </Link>

      <div className="bg-white shadow rounded-lg overflow-hidden mb-8">
        <div className="md:flex">
          <div className="md:flex-shrink-0 md:w-1/3">
            <img 
              className="h-64 w-full object-cover md:h-full" 
              src={product.imagem_url || "https://picsum.photos/400/400"} 
              alt={product.nome} 
            />
          </div>
          <div className="p-8 md:w-2/3">
            <div className="uppercase tracking-wide text-sm text-emerald-500 font-semibold">{product.categoria}</div>
            <h1 className="mt-2 text-3xl font-extrabold text-gray-900 leading-tight">{product.nome}</h1>
            <p className="mt-4 text-gray-500">
              Compare os preços abaixo e escolha a melhor opção para sua economia.
            </p>
          </div>
        </div>
      </div>

      <h2 className="text-2xl font-bold text-gray-900 mb-6">Comparativo de Preços</h2>

      {comparisons.length === 0 ? (
        <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4">
          <div className="flex">
            <div className="ml-3">
              <p className="text-sm text-yellow-700">
                Ainda não há preços cadastrados para este produto.
              </p>
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {comparisons.map((comp, idx) => (
            <div 
              key={idx} 
              className={`relative bg-white rounded-lg shadow p-6 flex flex-col sm:flex-row items-center justify-between border-2 ${comp.isLowest ? 'border-emerald-500' : 'border-transparent'}`}
            >
              {comp.isLowest && (
                <div className="absolute top-0 right-0 bg-emerald-500 text-white text-xs font-bold px-3 py-1 rounded-bl-lg rounded-tr-sm uppercase">
                  Melhor Preço
                </div>
              )}

              <div className="flex items-center mb-4 sm:mb-0">
                <div className={`p-3 rounded-full ${comp.isLowest ? 'bg-emerald-100 text-emerald-600' : 'bg-gray-100 text-gray-600'}`}>
                  <Store size={24} />
                </div>
                <div className="ml-4">
                  <h3 className="text-lg font-bold text-gray-900">{comp.marketName}</h3>
                  <div className="flex items-center text-sm text-gray-500 mt-1">
                    <Calendar size={14} className="mr-1" />
                    Atualizado em: {new Date(comp.lastUpdate).toLocaleDateString('pt-BR')}
                  </div>
                </div>
              </div>

              <div className="text-right">
                <span className="block text-3xl font-extrabold text-gray-900">
                  R$ {comp.price.toFixed(2).replace('.', ',')}
                </span>
                {comp.isLowest && (
                  <span className="text-emerald-600 text-sm font-medium">Você economiza!</span>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

