import React, { useState, useEffect } from 'react';
import { Save } from 'lucide-react';
import { DB } from '../../services/db';
import { Market, Product, Price } from '../../types';

export const ManagePrices: React.FC = () => {
  const [markets, setMarkets] = useState<Market[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [prices, setPrices] = useState<Price[]>([]);

  const [selectedMarketId, setSelectedMarketId] = useState<string>('');
  const [selectedProductId, setSelectedProductId] = useState<string>('');
  const [priceValue, setPriceValue] = useState<string>('');
  const [feedback, setFeedback] = useState<{msg: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    setMarkets(DB.getMarkets());
    setProducts(DB.getProducts());
    setPrices(DB.getPrices());
  }, []);

  // Update input if price already exists for selection
  useEffect(() => {
    if (selectedMarketId && selectedProductId) {
      const existingPrice = prices.find(p => p.mercado_id === selectedMarketId && p.produto_id === selectedProductId && p.ativo);
      if (existingPrice) {
        setPriceValue(existingPrice.valor.toString());
      } else {
        setPriceValue('');
      }
    }
  }, [selectedMarketId, selectedProductId, prices]);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedMarketId || !selectedProductId || !priceValue) {
      setFeedback({ msg: 'Preencha todos os campos.', type: 'error' });
      return;
    }

    const numValue = parseFloat(priceValue);
    if (numValue <= 0) {
      setFeedback({ msg: 'O preço deve ser maior que zero.', type: 'error' });
      return;
    }

    const newPrice: Price = {
      id: `pr${Date.now()}`,
      mercado_id: selectedMarketId,
      produto_id: selectedProductId,
      valor: numValue,
      ativo: true,
      data_atualizacao: new Date().toISOString()
    };

    DB.savePrice(newPrice);
    setPrices(DB.getPrices()); // Refresh local list
    setFeedback({ msg: 'Preço atualizado com sucesso!', type: 'success' });

    // Clear feedback after 3s
    setTimeout(() => setFeedback(null), 3000);
  };

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-10">
      <h1 className="text-2xl font-bold text-gray-900 mb-6">Gerenciar Preços</h1>

      <div className="bg-white shadow sm:rounded-lg p-6">
        <form onSubmit={handleSave} className="space-y-6">

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-gray-700">Selecione o Mercado</label>
              <select
                required
                value={selectedMarketId}
                onChange={(e) => setSelectedMarketId(e.target.value)}
                className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-emerald-500 focus:border-emerald-500 sm:text-sm rounded-md border"
              >
                <option value="">-- Selecione --</option>
                {markets.map(m => (
                  <option key={m.id} value={m.id}>{m.nome}</option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700">Selecione o Produto</label>
              <select
                required
                value={selectedProductId}
                onChange={(e) => setSelectedProductId(e.target.value)}
                className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-emerald-500 focus:border-emerald-500 sm:text-sm rounded-md border"
              >
                <option value="">-- Selecione --</option>
                {products.map(p => (
                  <option key={p.id} value={p.id}>{p.nome}</option>
                ))}
              </select>
            </div>
          </div>

          <div>
             <label className="block text-sm font-medium text-gray-700">Preço (R$)</label>
             <div className="mt-1 relative rounded-md shadow-sm w-full sm:w-1/3">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <span className="text-gray-500 sm:text-sm">R$</span>
                </div>
                <input
                  type="number"
                  step="0.01"
                  min="0.01"
                  required
                  value={priceValue}
                  onChange={(e) => setPriceValue(e.target.value)}
                  className="focus:ring-emerald-500 focus:border-emerald-500 block w-full pl-10 pr-12 sm:text-sm border-gray-300 rounded-md py-2 border"
                  placeholder="0.00"
                />
             </div>
          </div>

          {feedback && (
            <div className={`p-4 rounded-md ${feedback.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
              {feedback.msg}
            </div>
          )}

          <div className="flex justify-end">
            <button
              type="submit"
              className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-emerald-600 hover:bg-emerald-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-emerald-500"
            >
              <Save className="mr-2 h-5 w-5" />
              Salvar Preço
            </button>
          </div>
        </form>
      </div>

      <div className="mt-8">
        <h3 className="text-lg font-medium text-gray-900">Histórico Recente</h3>
        <p className="text-sm text-gray-500 mb-4">Últimos preços cadastrados no sistema.</p>

        <div className="bg-white shadow overflow-hidden sm:rounded-lg">
           <ul className="divide-y divide-gray-200">
             {prices.slice(-5).reverse().map(price => {
               const pName = products.find(p => p.id === price.produto_id)?.nome || 'Produto desconhecido';
               const mName = markets.find(m => m.id === price.mercado_id)?.nome || 'Mercado desconhecido';
               return (
                 <li key={price.id} className="px-4 py-4 sm:px-6">
                    <div className="flex items-center justify-between">
                      <div className="text-sm font-medium text-emerald-600 truncate">
                        {pName}
                      </div>
                      <div className="ml-2 flex-shrink-0 flex">
                        <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">
                          R$ {price.valor.toFixed(2)}
                        </span>
                      </div>
                    </div>
                    <div className="mt-2 sm:flex sm:justify-between">
                      <div className="sm:flex">
                        <p className="flex items-center text-sm text-gray-500">
                           em {mName}
                        </p>
                      </div>
                      <div className="mt-2 flex items-center text-sm text-gray-500 sm:mt-0">
                        <p>
                          Atualizado em: {new Date(price.data_atualizacao).toLocaleDateString()}
                        </p>
                      </div>
                    </div>
                 </li>
               )
             })}
           </ul>
        </div>
      </div>
    </div>
  );
};

