import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Zap, Image as ImageIcon, QrCode, ScanLine } from 'lucide-react';

export const Scan: React.FC = () => {
  const navigate = useNavigate();
  const [scanning, setScanning] = useState(true);
  const [flash, setFlash] = useState(false);

  useEffect(() => {
    // Simula a detecção automática após 3 segundos
    const timer = setTimeout(() => {
      setScanning(false);
      // Simula o redirecionamento para o primeiro produto do mock para fins de demo
      setTimeout(() => {
        navigate('/product/p1');
      }, 1000);
    }, 3500);

    return () => clearTimeout(timer);
  }, [navigate]);

  return (
    <div className="fixed inset-0 bg-black z-50 flex flex-col">
      {/* Header do Scanner */}
      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between items-center z-10 bg-gradient-to-b from-black/60 to-transparent">
        <button 
          onClick={() => navigate(-1)} 
          className="w-10 h-10 bg-white/10 backdrop-blur-md rounded-full flex items-center justify-center text-white"
        >
          <ArrowLeft size={20} />
        </button>
        <h2 className="text-white font-bold text-sm tracking-widest uppercase">Escanear Produto</h2>
        <button 
          onClick={() => setFlash(!flash)}
          className={`w-10 h-10 backdrop-blur-md rounded-full flex items-center justify-center transition-colors ${flash ? 'bg-yellow-400 text-black' : 'bg-white/10 text-white'}`}
        >
          <Zap size={20} fill={flash ? "currentColor" : "none"} />
        </button>
      </div>

      {/* Viewfinder (Visor) */}
      <div className="flex-1 relative flex items-center justify-center px-8">
        {/* Cam Simulation Overlay */}
        <div className="absolute inset-0 opacity-40 bg-[url('https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1000')] bg-cover bg-center grayscale" />

        {/* Scan Area */}
        <div className="relative w-full aspect-square max-w-xs">
          {/* Corners */}
          <div className="absolute top-0 left-0 w-10 h-10 border-t-4 border-l-4 border-emerald-500 rounded-tl-3xl"></div>
          <div className="absolute top-0 right-0 w-10 h-10 border-t-4 border-r-4 border-emerald-500 rounded-tr-3xl"></div>
          <div className="absolute bottom-0 left-0 w-10 h-10 border-b-4 border-l-4 border-emerald-500 rounded-bl-3xl"></div>
          <div className="absolute bottom-0 right-0 w-10 h-10 border-b-4 border-r-4 border-emerald-500 rounded-br-3xl"></div>

          {/* Animated Scan Line */}
          {scanning && (
            <div className="absolute left-4 right-4 h-1 bg-emerald-500/50 shadow-[0_0_15px_rgba(16,185,129,0.8)] rounded-full animate-[scan_2s_ease-in-out_infinite]"></div>
          )}

          {/* Success Marker */}
          {!scanning && (
            <div className="absolute inset-0 flex items-center justify-center bg-emerald-500/20 animate-pulse rounded-3xl">
              <div className="bg-white p-4 rounded-full text-emerald-600 shadow-xl">
                <QrCode size={48} />
              </div>
            </div>
          )}
        </div>

        {/* Instructions */}
        <div className="absolute bottom-32 text-center w-full px-6">
          <p className="text-white font-medium text-lg mb-2">
            {scanning ? 'Posicione o código de barras' : 'Código identificado!'}
          </p>
          <p className="text-gray-400 text-sm">
            {scanning ? 'A detecção será automática e rápida' : 'Carregando detalhes do produto...'}
          </p>
        </div>
      </div>

      {/* Bottom Actions */}
      <div className="p-8 flex justify-center gap-12 bg-gradient-to-t from-black/80 to-transparent">
        <button className="flex flex-col items-center gap-2 text-white/60 hover:text-white transition-colors">
          <div className="w-12 h-12 rounded-2xl bg-white/10 flex items-center justify-center">
            <ImageIcon size={24} />
          </div>
          <span className="text-[10px] font-bold uppercase tracking-widest">Galeria</span>
        </button>
        <button className="flex flex-col items-center gap-2 text-white/60 hover:text-white transition-colors">
          <div className="w-12 h-12 rounded-2xl bg-white/10 flex items-center justify-center">
            <ScanLine size={24} />
          </div>
          <span className="text-[10px] font-bold uppercase tracking-widest">Digitar</span>
        </button>
      </div>

      <style>{`
        @keyframes scan {
          0%, 100% { top: 10%; opacity: 0.3; }
          50% { top: 90%; opacity: 1; }
        }
      `}</style>
    </div>
  );
};

