import React from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import { Navbar } from './components/Navbar';
import { BottomNav } from './components/BottomNav';
import { Home } from './pages/Home';
import { ProductDetails } from './pages/ProductDetails';
import { Explore } from './pages/Explore';
import { Scan } from './pages/Scan';
import { Login } from './pages/Login';
import { Profile } from './pages/Profile';
import { Dashboard } from './pages/admin/Dashboard';
import { ManageProducts } from './pages/admin/ManageProducts';
import { ManageMarkets } from './pages/admin/ManageMarkets';
import { ManagePrices } from './pages/admin/ManagePrices';

const PrivateRoute: React.FC<{ children: React.ReactElement, requireAdmin?: boolean }> = ({ children, requireAdmin = false }) => {
  const { user, isAdmin } = useAuth();

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  if (requireAdmin && !isAdmin) {
    return <Navigate to="/" replace />;
  }

  return children;
};

const AppContent: React.FC = () => {
  const { user } = useAuth();

  return (
    <div className="flex flex-col min-h-screen bg-slate-50">
      {user && <Navbar />}
      <main className={`flex-grow ${user ? 'pb-24 md:pb-8' : ''}`}>
        <Routes>
          {/* Public/Auth Route */}
          <Route path="/login" element={user ? <Navigate to="/" /> : <Login />} />

          {/* Protected Routes */}
          <Route path="/" element={<PrivateRoute><Home /></PrivateRoute>} />
          <Route path="/explore" element={<PrivateRoute><Explore /></PrivateRoute>} />
          <Route path="/scan" element={<PrivateRoute><Scan /></PrivateRoute>} />
          <Route path="/product/:id" element={<PrivateRoute><ProductDetails /></PrivateRoute>} />
          <Route path="/profile" element={<PrivateRoute><Profile /></PrivateRoute>} />

          {/* Admin Routes */}
          <Route path="/admin/dashboard" element={<PrivateRoute requireAdmin><Dashboard /></PrivateRoute>} />
          <Route path="/admin/products" element={<PrivateRoute requireAdmin><ManageProducts /></PrivateRoute>} />
          <Route path="/admin/markets" element={<PrivateRoute requireAdmin><ManageMarkets /></PrivateRoute>} />
          <Route path="/admin/prices" element={<PrivateRoute requireAdmin><ManagePrices /></PrivateRoute>} />

          {/* Fallback */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </main>
      {user && <BottomNav />}
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AuthProvider>
      <HashRouter>
        <AppContent />
      </HashRouter>
    </AuthProvider>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
