import { ArrowLeft, Zap, Image as ImageIcon, QrCode, ScanLine, CheckCircle2, Loader2, ShieldCheck } from 'lucide-react';

export const Scan: React.FC = () => {
  const navigate = useNavigate();
  const [status, setStatus] = useState<'scanning' | 'processing' | 'success'>('scanning');
  const [flash, setFlash] = useState(false);

  useEffect(() => {
    if (status === 'processing') {
      const timer = setTimeout(() => {
        setStatus('success');
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [status]);

  const handleSimulateDetection = () => {
    if (status === 'scanning') {
      setStatus('processing');
    }
  };

  return (
    <div className="fixed inset-0 bg-black z-50 flex flex-col">
      {/* Header do Scanner */}
      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between items-center z-10 bg-gradient-to-b from-black/60 to-transparent">
        <button 
          onClick={() => navigate(-1)} 
          className="w-10 h-10 bg-white/10 backdrop-blur-md rounded-full flex items-center justify-center text-white"
        >
          <ArrowLeft size={20} />
        </button>
        <h2 className="text-white font-bold text-xs tracking-widest uppercase">
          {status === 'scanning' ? 'Escanear QR Code' : 'Processando'}
        </h2>
        <button 
          onClick={() => setFlash(!flash)}
          className={`w-10 h-10 backdrop-blur-md rounded-full flex items-center justify-center transition-colors ${flash ? 'bg-yellow-400 text-black' : 'bg-white/10 text-white'}`}
        >
          <Zap size={20} fill={flash ? "currentColor" : "none"} />
        </button>
