      <div className="flex-1 relative flex items-center justify-center px-8 overflow-hidden">
        {/* Cam Simulation Overlay */}
        <div className={`absolute inset-0 transition-opacity duration-700 ${status === 'success' ? 'opacity-20' : 'opacity-40'} bg-[url('https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1000')] bg-cover bg-center grayscale`} />

        {/* Main Interface Logic */}
        {status === 'scanning' && (
